<h3 class="font-label-caps text-label-caps uppercase font-bold text-primary tracking-widest">7-DAY ATELIER GUARANTEE</h3>
<p class="font-body-md text-body-md text-on-surface-variant">
            Hassle-free size swaps and silhouette adjustments managed through our Makati Studio concierge.
          </p>
</div>
</div>
</div>
</section>
<!-- Client-side Interactive Behaviors: Grid Toggle, Quick-Add Toast Notification -->
<div class="fixed bottom-6 right-6 z-50 transform translate-y-24 opacity-0 transition-all duration-300 pointer-events-none" id="quick-cart-toast">
<div class="bg-primary text-on-primary px-space-md py-space-sm shadow-xl flex items-center gap-space-sm">
<span class="material-symbols-outlined text-[20px] text-on-primary">check_circle</span>
<div>
<span class="font-label-caps text-label-caps uppercase font-bold block">GARMENT ADDED TO ARCHIVE BAG</span>
<span class="font-label-sm text-label-sm text-on-primary/80">READY FOR PHILIPPINE CHECKOUT</span>
</div>
</div>
</div>
<script>
    (function() {
      // Grid view switcher behavior
      const btnGrid2 = document.getElementById('view-grid-2');
      const btnGrid4 = document.getElementById('view-grid-4');
      const container = document.getElementById('catalog-products-container');
      const toast = document.getElementById('quick-cart-toast');
      const categoryScroller = document.getElementById('category-filters');
      const categoryNext = document.getElementById('category-next');
      const categoryPrev = document.getElementById('category-prev');
      const catalogSort = document.getElementById('catalog-sort');
      const catalogCards = container ? Array.from(container.querySelectorAll(':scope > article[data-product-slug]')) : [];
      const resultsCount = document.getElementById('catalog-results-count');
      const displayCount = document.getElementById('catalog-display-count');
      const categoryButtons = document.querySelectorAll('#category-filters [data-filter]');
      const queryParams = new URLSearchParams(window.location.search);
      const requestedCategory = queryParams.get('category');
      const requestedSort = queryParams.get('sort');
      let activeFilter = 'all';
      if (['oversized', 'heavyweight', 'trousers', 'accessories'].includes(requestedCategory)) {
        activeFilter = requestedCategory;
      }
      if (['featured', 'newest', 'price-low', 'price-high', 'weight'].includes(requestedSort) && catalogSort) {
        catalogSort.value = requestedSort;
      }
      const activeNavPath = requestedCategory === 'oversized' ? 'oversized-shirts'
        : requestedCategory === 'heavyweight' ? 'heavyweight-basics'
        : requestedCategory === 'trousers' ? 'tailored-trousers'
        : requestedCategory === 'accessories' ? 'architectural-accessories'
        : requestedSort === 'newest' ? 'new-arrivals'
        : 'shop-all';
      document.querySelectorAll('header nav [data-path]').forEach((link) => {
        const selected = link.dataset.path === activeNavPath;
        link.classList.toggle('text-primary', selected);
        link.classList.toggle('font-bold', selected);
        link.classList.toggle('text-on-surface-variant', !selected);
        link.classList.toggle('border-b', selected);
        link.classList.toggle('border-primary', selected);
        link.classList.toggle('underline', selected);
        link.setAttribute('aria-current', selected ? 'page' : 'false');
      });
      const cardParams = {
        'k-01-structural-boxy-tee': { availability: 'ready', sizes: 'S,M,L,XL', colors: 'onyx', silhouettes: 'boxy' },
        'brutalist-monolith-cuff-ring-set': { availability: 'limited', sizes: 'OS', colors: 'onyx', silhouettes: 'tapered' },
        'k-02-dropped-raglan-longline': { availability: 'ready', sizes: 'S,M,L', colors: 'concrete', silhouettes: 'raglan' },
        'geometric-carabiner-key-tether': { availability: 'ready', sizes: 'OS', colors: 'onyx', silhouettes: 'tapered' },
        'k-03-wide-leg-pleated-cargo': { availability: 'limited', sizes: 'S,M,L,XL', colors: 'onyx', silhouettes: 'tapered' },
        'atelier-heavyweight-tank': { availability: 'ready', sizes: 'S,M,L,XL', colors: 'onyx,bone', silhouettes: 'boxy' },
        'modular-crossbody-chest-rig': { availability: 'limited', sizes: 'OS', colors: 'onyx', silhouettes: 'tapered' },
        'k-04-sculpted-oversized-hoodie': { availability: 'ready', sizes: 'S,M,L,XL', colors: 'concrete', silhouettes: 'boxy' },
        'k-05-structural-raglan-crew': { availability: 'ready', sizes: 'S,M,L,XL', colors: 'concrete', silhouettes: 'raglan' },
        'k-06-washed-cargo-tee': { availability: 'ready', sizes: 'S,M,L,XL', colors: 'onyx', silhouettes: 'boxy' },
        'k-07-raw-cut-box-tee': { availability: 'limited', sizes: 'S,M,L,XL', colors: 'bone', silhouettes: 'cropped' },
        'k-08-sculpted-concrete-hoodie': { availability: 'ready', sizes: 'S,M,L,XL', colors: 'concrete', silhouettes: 'boxy' },
        'k-09-modular-field-cargo': { availability: 'limited', sizes: 'S,M,L,XL', colors: 'rust', silhouettes: 'tapered' },
        'k-10-wide-pleat-trouser': { availability: 'ready', sizes: 'S,M,L,XL', colors: 'onyx', silhouettes: 'tapered' },
        'k-11-modular-chest-harness': { availability: 'limited', sizes: 'OS', colors: 'onyx', silhouettes: 'tapered' },
      };
      const selectedParams = { availability: new Set(), gsm: new Set(), size: new Set(), color: new Set(), silhouette: new Set() };
      const parametricControls = document.querySelectorAll('.parametric-control:not([data-param="price"])');
      const priceRange = document.getElementById('catalog-price-range');
      const priceRangeValue = document.getElementById('catalog-price-range-value');
      const updatePriceRangeVisual = () => {
        if (!priceRange) return;
        const min = Number(priceRange.min || 0);
        const max = Number(priceRange.max || 100);
        const value = Number(priceRange.value || max);
        const progress = ((value - min) / Math.max(max - min, 1)) * 100;
        priceRange.style.setProperty('--price-progress', `${progress}%`);
        if (priceRangeValue) {
          priceRangeValue.textContent = `UP TO ₱${value.toLocaleString('en-PH')}`;
          priceRangeValue.classList.add('is-updating');
          window.setTimeout(() => priceRangeValue.classList.remove('is-updating'), 120);
        }
      };
      const updateControlStyle = (element, selected) => {
        element.classList.toggle('bg-primary', selected);
        element.classList.toggle('text-on-primary', selected);
        element.classList.toggle('font-bold', selected);
        element.classList.toggle('bg-surface', !selected);
        element.classList.toggle('bg-surface-container', !selected);
        element.classList.toggle('text-on-surface', !selected);
        element.classList.toggle('parametric-selected', selected);
      };

      catalogCards.forEach((card) => {
        card.classList.add('catalog-product-card');
        const params = cardParams[card.dataset.productSlug] || {};
        card.dataset.availability = params.availability || 'ready';
        card.dataset.sizes = params.sizes || 'S,M,L,XL';
        card.dataset.colors = params.colors || 'onyx';
        card.dataset.silhouettes = params.silhouettes || 'boxy';
      });

      if (container && catalogCards.length) {
        const filterTransitionMs = 180;
        const emptyState = document.createElement('div');
        emptyState.className = 'col-span-full hidden border border-surface-container-highest bg-surface-container-lowest px-space-md py-space-3xl text-center';
        emptyState.innerHTML = '<span class="material-symbols-outlined text-4xl text-secondary">inventory_2</span><p class="mt-space-sm font-label-caps text-label-caps uppercase tracking-widest text-secondary">NO PIECES MATCH THIS COLLECTION</p>';
        container.appendChild(emptyState);

        const applyCatalogControls = () => {
          updatePriceRangeVisual();
          const sortValue = catalogSort?.value || 'featured';
          const sortedCards = [...catalogCards].sort((a, b) => {
            if (sortValue === 'price-low') return Number(a.dataset.price) - Number(b.dataset.price);
            if (sortValue === 'price-high') return Number(b.dataset.price) - Number(a.dataset.price);
            if (sortValue === 'weight') return Number(b.dataset.gsm) - Number(a.dataset.gsm);
            if (sortValue === 'newest') return catalogCards.indexOf(b) - catalogCards.indexOf(a);
            return catalogCards.indexOf(a) - catalogCards.indexOf(b);
          });

          sortedCards.forEach((card) => {
            const params = cardParams[card.dataset.productSlug] || {};
            const matchesCategory = activeFilter === 'all' || card.dataset.category === activeFilter;
            const matchesParams = Object.entries(selectedParams).every(([param, values]) => {
              if (!values.size) return true;
              const cardValues = (param === 'availability' ? params.availability : param === 'gsm' ? card.dataset.gsm : param === 'size' ? params.sizes : param === 'color' ? params.colors : params.silhouettes)?.split(',') || [];
              return [...values].some((value) => cardValues.includes(value));
            });
            const priceLimit = Number(document.getElementById('catalog-price-range')?.value || 5000);
            const matchesPrice = Number(card.dataset.price) <= priceLimit;
            const matches = matchesCategory && matchesParams && matchesPrice;
            window.clearTimeout(card._catalogFilterTimer);
            if (matches) {
              const wasHidden = card.classList.contains('hidden');
              card.classList.remove('hidden', 'catalog-card-exit');
              if (wasHidden) {
                card.classList.add('catalog-card-enter');
                window.requestAnimationFrame(() => {
                  window.requestAnimationFrame(() => card.classList.remove('catalog-card-enter'));
                });
              }
            } else if (!card.classList.contains('hidden')) {
              card.classList.add('catalog-card-exit');
              card._catalogFilterTimer = window.setTimeout(() => {
                card.classList.add('hidden');
                card.classList.remove('catalog-card-exit');
              }, filterTransitionMs);
            }
            container.appendChild(card);
          });

          const visibleCount = sortedCards.filter((card) => !card.classList.contains('hidden')).length;
          emptyState.classList.toggle('hidden', visibleCount > 0);
          if (resultsCount) resultsCount.textContent = `SHOWING ${visibleCount} ARCHIVAL SPECS`;
          if (displayCount) displayCount.textContent = `DISPLAYING ${visibleCount} OF ${catalogCards.length} ARCHIVAL PIECES`;
        };

        categoryButtons.forEach((button) => {
          button.addEventListener('click', () => {
            activeFilter = button.dataset.filter;
            categoryButtons.forEach((item) => {
              const selected = item === button;
              item.classList.toggle('bg-primary', selected);
              item.classList.toggle('text-on-primary', selected);
              item.classList.toggle('font-bold', selected);
              item.classList.toggle('shadow-sm', selected);
              item.classList.toggle('bg-surface-container', !selected);
              item.classList.toggle('text-on-surface', !selected);
            });
            applyCatalogControls();
          });
        });

        catalogSort?.addEventListener('change', applyCatalogControls);
        parametricControls.forEach((control) => {
          control.addEventListener(control.type === 'checkbox' ? 'change' : 'click', () => {
            const param = control.dataset.param;
            const value = control.dataset.value;
            const alreadySelected = selectedParams[param].has(value);
            if (control.type !== 'checkbox' && (param === 'size' || param === 'color')) {
              selectedParams[param].clear();
              document.querySelectorAll(`[data-param="${param}"]`).forEach((item) => updateControlStyle(item, false));
            }
            if (control.type === 'checkbox') {
              control.checked ? selectedParams[param].add(value) : selectedParams[param].delete(value);
            } else if (alreadySelected) {
              selectedParams[param].delete(value);
            } else {
              selectedParams[param].add(value);
            }
            updateControlStyle(control, selectedParams[param].has(value));
            applyCatalogControls();
          });
        });
        priceRange?.addEventListener('input', applyCatalogControls);
        const changePriceRange = (direction) => {
          if (!priceRange) return;
          const step = Number(priceRange.step || 1);
          const min = Number(priceRange.min || 0);
          const max = Number(priceRange.max || 100);
          const nextValue = Math.min(max, Math.max(min, Number(priceRange.value) + (direction * step)));
          if (nextValue === Number(priceRange.value)) return;
          priceRange.value = nextValue;
          priceRange.dispatchEvent(new Event('input', { bubbles: true }));
          priceRange.focus({ preventScroll: true });
        };
        document.getElementById('catalog-price-decrease')?.addEventListener('click', () => changePriceRange(-1));
        document.getElementById('catalog-price-increase')?.addEventListener('click', () => changePriceRange(1));
        document.getElementById('reset-parametric-filters')?.addEventListener('click', () => {
          Object.values(selectedParams).forEach((values) => values.clear());
          parametricControls.forEach((control) => {
            if (control.type === 'checkbox') control.checked = false;
            updateControlStyle(control, false);
          });
          if (priceRange) priceRange.value = priceRange.max;
          activeFilter = 'all';
          categoryButtons.forEach((item) => {
            const selected = item.dataset.filter === 'all';
            item.classList.toggle('bg-primary', selected);
            item.classList.toggle('text-on-primary', selected);
            item.classList.toggle('font-bold', selected);
            item.classList.toggle('shadow-sm', selected);
            item.classList.toggle('bg-surface-container', !selected);
            item.classList.toggle('text-on-surface', !selected);
          });
          applyCatalogControls();
        });
        const requestedButton = [...categoryButtons].find((button) => button.dataset.filter === activeFilter);
        if (requestedButton) {
          categoryButtons.forEach((item) => {
            const selected = item === requestedButton;
            item.classList.toggle('bg-primary', selected);
            item.classList.toggle('text-on-primary', selected);
            item.classList.toggle('font-bold', selected);
            item.classList.toggle('shadow-sm', selected);
            item.classList.toggle('bg-surface-container', !selected);
            item.classList.toggle('text-on-surface', !selected);
          });
        }
        applyCatalogControls();
      }

      if (categoryScroller && categoryNext && categoryPrev) {
        const updateCategoryNext = () => {
          const hasMore = categoryScroller.scrollWidth > categoryScroller.clientWidth + 2;
          const atEnd = categoryScroller.scrollLeft + categoryScroller.clientWidth >= categoryScroller.scrollWidth - 2;
          const atStart = categoryScroller.scrollLeft <= 2;
          categoryNext.classList.toggle('hidden', !hasMore || atEnd);
          categoryPrev.classList.toggle('hidden', !hasMore || atStart);
        };

        categoryNext.addEventListener('click', () => {
          categoryScroller.scrollBy({ left: Math.max(220, categoryScroller.clientWidth * 0.65), behavior: 'smooth' });
        });
        categoryPrev.addEventListener('click', () => {
          categoryScroller.scrollBy({ left: -Math.max(220, categoryScroller.clientWidth * 0.65), behavior: 'smooth' });
        });
        categoryScroller.addEventListener('scroll', updateCategoryNext, { passive: true });
        window.addEventListener('resize', updateCategoryNext);
        updateCategoryNext();
      }

      if (btnGrid2 && btnGrid4 && container) {
        btnGrid2.addEventListener('click', function() {
          container.className = 'grid grid-cols-1 sm:grid-cols-2 gap-space-lg';
          btnGrid2.classList.add('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
          btnGrid2.classList.remove('text-on-surface-variant');
          btnGrid4.classList.remove('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
          btnGrid4.classList.add('text-on-surface-variant');
        });

        btnGrid4.addEventListener('click', function() {
          container.className = 'grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-space-md';
          btnGrid4.classList.add('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
          btnGrid4.classList.remove('text-on-surface-variant');
          btnGrid2.classList.remove('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
          btnGrid2.classList.add('text-on-surface-variant');
        });
      }

      // Quick Add Interactive Feedback
      const quickAddButtons = document.querySelectorAll('button:has(.material-symbols-outlined)');
      quickAddButtons.forEach(btn => {
        if (btn.textContent.includes('QUICK ADD')) {
          btn.addEventListener('click', function(e) {
            e.preventDefault();
            if (toast) {
              toast.classList.remove('translate-y-24', 'opacity-0');
              toast.classList.add('translate-y-0', 'opacity-100');
              setTimeout(() => {
                toast.classList.add('translate-y-24', 'opacity-0');
                toast.classList.remove('translate-y-0', 'opacity-100');
              }, 2500);
            }
          });
        }
      });
    })();
  </script>
