<script>
  // Public product cards use the same values edited in Product Inventory.
  const managedInventory = @json($inventory);
  const shopRoute = @json(route('shop'));
  const collectionLinks = {
    'shop-all': shopRoute,
    'new-arrivals': `${shopRoute}?sort=newest`,
    'oversized-shirts': `${shopRoute}?category=oversized`,
    'heavyweight-basics': `${shopRoute}?category=heavyweight`,
    'architectural-accessories': `${shopRoute}?category=accessories`,
  };
  Object.entries(collectionLinks).forEach(([path, url]) => {
    document.querySelectorAll(`[data-path="${path}"]`).forEach((link) => {
      link.href = url;
      link.addEventListener('click', (event) => {
        event.preventDefault();
        window.location.assign(url);
      });
    });
  });
  document.querySelectorAll('[data-path="lookbook-ss25"]').forEach((link) => {
    link.href = @json(route('lookbook'));
  });
  const managedPrice = (value) => '₱' + Number(value).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  document.querySelectorAll('#catalog-products-container [data-product-slug]').forEach(card => {
    const item = managedInventory[card.dataset.productSlug];
      if (!item) { card.style.display = 'none'; return; }
      card.querySelector('h3')?.replaceChildren(document.createTextNode(item.name));
      if (item.image) card.querySelector('img')?.setAttribute('src', item.image);
    card.querySelectorAll('.font-price-lg').forEach(price => price.textContent = managedPrice(item.price));
    card.querySelectorAll('button[onclick*="handleAddToCart"]').forEach(button => {
      button.setAttribute('onclick', `handleAddToCart(${JSON.stringify(item.name)}, ${JSON.stringify(managedPrice(item.price))})`);
    });
    card.dataset.price = item.price;
  });
</script>
<script>window.customerAuthenticated = @json(session()->has('customer_login')); window.customerAvatar = @json(session('customer_profile.avatar'));</script><script src="{{ asset('js/app.js') }}"></script></body></html>
